34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.service.ClinicService;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
41	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        rejectBlankOwnerFields(ownerFieldsDto);
106	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
107	        rejectDuplicateTelephone(normalizedTelephone);
108	        ownerFieldsDto.setTelephone(normalizedTelephone);
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        this.clinicService.saveOwner(owner);
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        headers.setLocation(UriComponentsBuilder.newInstance()
114	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
115	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
121	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
122	        if (currentOwner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        currentOwner.setAddress(ownerFieldsDto.getAddress());
126	        currentOwner.setCity(ownerFieldsDto.getCity());
127	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
128	        currentOwner.setLastName(ownerFieldsDto.getLastName());
129	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
130	        this.clinicService.saveOwner(currentOwner);
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Transactional
136	    @Override
137	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        this.clinicService.deleteOwner(owner);
143	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Pet pet = petMapper.toPet(petFieldsDto);
155	        owner.setId(ownerId);
156	        pet.setOwner(owner);
157	        pet.getType().setName(null);
158	        this.clinicService.savePet(pet);
159	        PetDto petDto = petMapper.toPetDto(pet);
160	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
161	            .buildAndExpand(pet.getId()).toUri());
162	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner != null) {
170	            Pet currentPet = this.clinicService.findPetById(petId);
171	            if (currentPet != null) {
172	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
173	                currentPet.setName(petFieldsDto.getName());
174	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
175	                this.clinicService.savePet(currentPet);
176	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	            }
178	        }
179	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
185	        HttpHeaders headers = new HttpHeaders();
186	        Visit visit = visitMapper.toVisit(visitFieldsDto);
187	        Pet pet = new Pet();
188	        pet.setId(petId);
189	        visit.setPet(pet);
190	        this.clinicService.saveVisit(visit);
191	        VisitDto visitDto = visitMapper.toVisitDto(visit);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
193	            .buildAndExpand(visit.getId()).toUri());
194	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
195	    }
196	
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner != null) {
203	            Pet pet = owner.getPet(petId);
204	            if (pet != null) {
205	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
